-- 1.6.11 site texts for the owner's draft: the new «القادم» list, the «طريقة العمل» page and today's review date.
-- Writes the DRAFT only; the owner publishes it from the owner interface. Applied on TEST 2026-11-10; LIVE at release.
update public.site_config set data = jsonb_set(jsonb_set(jsonb_set(data,'{roadmap}',$j$[{"t": {"ar": "مصدر رسمي لكل رقم", "en": "An official source for every number"}, "d": {"ar": "كل جرعة وتداخل يحمل اسم مصدره ورقمه من النشرات الرسمية، وبالنقر عليه تنتقل إليه في قائمة المصادر.", "en": "Every dose and interaction carries the name and number of its official source; tap it to open it in the sources list."}, "go": "sources", "ic": "chart", "st": "now"}, {"t": {"ar": "العربية والإنجليزية والوضع الليلي", "en": "Arabic, English and dark mode"}, "d": {"ar": "زر للغة وزر للمظهر في أعلى الصفحة، والموقع يتذكر اختيارك، والطباعة فاتحة دائماً.", "en": "A language button and an appearance button at the top; the site remembers your choice, and printing is always light."}, "go": "calc", "ic": "plus", "st": "now"}, {"t": {"ar": "294 تداخلاً مع مصادرها", "en": "294 interactions with their sources"}, "d": {"ar": "تداخلات المضادات مع الأدوية والأطعمة والمنتجات، وتوقيت الأخذ، لكل مضاد في بطاقة مع بحث بالاسم أو الصنف.", "en": "Antibiotic interactions with medicines, foods and products, with timing, one card per antibiotic with search by name or class."}, "go": "interactions", "ic": "share", "st": "now"}, {"t": {"ar": "حاسبة جرعات لـ 100 مضاد حيوي", "en": "A dose calculator for 100 antibiotics"}, "d": {"ar": "الجرعة حسب نوع العدوى والوزن ووظيفة الكلى (Cockcroft-Gault)، ولكل قاعدة مصدرها من نشرة الدواء الرسمية.", "en": "The dose by infection, weight and kidney function (Cockcroft-Gault); every rule comes from the official drug label."}, "go": "calc", "ic": "pill", "st": "now"}, {"t": {"ar": "جرعات الأطفال لكل الأدوية", "en": "Children doses for every drug"}, "d": {"ar": "بعض الحاسبات تعطي جرعة الأطفال كما في النشرة؛ الخطة إكمالها لكل الأدوية حسب الوزن والعمر.", "en": "Some calculators already give the children dose from the label; the plan is to cover every drug by weight and age."}, "ic": "baby", "st": "plan"}, {"t": {"ar": "تعديل الجرعة حسب وظيفة الكبد", "en": "Dose adjustment for liver function"}, "d": {"ar": "إضافة تعديل الجرعة في قصور الكبد (Child-Pugh) كما تذكره النشرات الرسمية.", "en": "Add dose adjustment in liver impairment (Child-Pugh) as the official labels state."}, "ic": "plus", "st": "plan"}, {"t": {"ar": "تداخلات المضادات مع بعضها", "en": "Interactions between antibiotics"}, "d": {"ar": "تداخل كل مضاد مع المضادات الأخرى، مثل الجمع الذي يزيد السمية أو يقلل الفعالية، مع المصدر.", "en": "How each antibiotic interacts with other antibiotics, such as combinations that raise toxicity or lower effect, with the source."}, "ic": "share", "st": "plan"}, {"t": {"ar": "تذكير بمدة العلاج", "en": "Treatment duration reminder"}, "d": {"ar": "تذكير بمدة العلاج الموصى بها لكل عدوى حسب المصدر الرسمي.", "en": "A reminder of the recommended treatment duration for each infection, following the official source."}, "ic": "clock", "st": "idea"}]$j$::jsonb),
 '{pages}', (select coalesce(jsonb_agg(p),'[]'::jsonb) from jsonb_array_elements(data->'pages') p where p->>'id'<>'method') || jsonb_build_array($j${"id": "method", "t": {"ar": "طريقة العمل", "en": "How it works"}, "b": {"ar": "## من أين تأتي المعلومات\n- كل جرعة وتداخل من **النشرة الرسمية للدواء**: FDA / DailyMed أولاً (أحدث نسخة)، وإن لم توجد فمن EMA أو eMC (بريطانيا) أو ANSM (فرنسا).\n- لكل نشرة رقم في قائمة المصادر مع اسمها وتاريخها ورابطها، ويظهر الرقم بجانب كل معلومة.\n- تصنيف **AWaRe** (وصول، مراقبة، احتياط) من منظمة الصحة العالمية 2023.\n\n## كيف تُحسب وظيفة الكلى\n- **تصفية الكرياتينين (Cockcroft-Gault):** (140 − العمر) × الوزن ÷ (72 × الكرياتينين) × 0.85 للنساء.\n- **الوزن المثالي:** 50 كغ للرجال و45.5 كغ للنساء، + 2.3 كغ لكل إنش فوق 152.4 سم (60 إنشاً).\n- **الوزن المعدّل:** إذا زاد الوزن الفعلي على 120% من المثالي = المثالي + 0.4 × (الفعلي − المثالي). وإذا حددت النشرة وزناً آخر للجرعة بالكيلوغرام تتبعها الحاسبة.\n- **eGFR (MDRD):** للأدوية التي تحدد نشرتها الجرعة بمعدل الترشيح: 175 × الكرياتينين^−1.154 × العمر^−0.203 × 0.742 للنساء.\n\n## كيف تُختار الجرعة\n- لكل دواء جدول قواعد مأخوذ من نشرته، مرتّب كما في النشرة.\n- تُفحص القواعد بالترتيب (نوع العدوى، التصفية، العمر، الوزن)، و**أول قاعدة تطابق** هي النتيجة، مع مصدرها.\n- إذا لم تذكر النشرة حداً رقمياً للكلى، تسأل الحاسبة **نعم / لا** بدل تخمين رقم.\n\n## المراجعة والجودة\n- أي محتوى طبي جديد أو معدّل لا يظهر للزوار حتى يعتمده الصيدلي المسؤول وينشره.\n- اختبارات آلية قبل كل نسخة: نحو 2000 فحص لقواعد الجرعات مقارنة بأرقام النشرات، وفحص الأدوية المئة ومصادرها، وفحص الواجهة على الهاتف والآيباد والكمبيوتر بالعربية والإنجليزية.\n\n## حدود الاستخدام\n- النتيجة مساعدة للصيدلي والطبيب، ولا تغني عن الحكم السريري ولا عن قراءة النشرة كاملة.", "en": "## Where the information comes from\n- Every dose and interaction comes from the **official drug label**: FDA / DailyMed first (newest version), otherwise EMA, eMC (UK) or ANSM (France).\n- Each label has a number in the sources list with its name, date and link, and that number appears next to every item.\n- The **AWaRe** group (Access, Watch, Reserve) is from the WHO 2023 classification.\n\n## How kidney function is calculated\n- **Creatinine clearance (Cockcroft-Gault):** (140 − age) × weight ÷ (72 × creatinine) × 0.85 for women.\n- **Ideal weight:** 50 kg for men and 45.5 kg for women, + 2.3 kg per inch above 152.4 cm (60 inches).\n- **Adjusted weight:** if actual weight is over 120% of ideal = ideal + 0.4 × (actual − ideal). If a label names another weight for mg/kg doses, the calculator follows it.\n- **eGFR (MDRD):** for drugs whose label doses by filtration rate: 175 × creatinine^−1.154 × age^−0.203 × 0.742 for women.\n\n## How the dose is chosen\n- Each drug has a table of rules taken from its label, in the label's order.\n- The rules are checked in order (infection, clearance, age, weight) and the **first rule that matches** is the result, with its source.\n- If the label gives no kidney number, the calculator asks **yes / no** instead of guessing a number.\n\n## Review and quality\n- New or edited medical content does not reach visitors until the responsible pharmacist approves and publishes it.\n- Automated tests before every version: about 2000 checks of the dose rules against the label numbers, a check of the 100 drugs and their sources, and the interface on phone, iPad and computer in Arabic and English.\n\n## Limits\n- The result supports the pharmacist and doctor; it does not replace clinical judgement or reading the full label."}}$j$::jsonb)),
 '{review,date}','"2026-11-10"') where id='draft' returning id, jsonb_array_length(data->'roadmap') rm, jsonb_array_length(data->'pages') pages, data->'review' rev
update public.site_config set data=jsonb_set(data,'{pages}',(select coalesce(jsonb_agg(p),'[]'::jsonb) from jsonb_array_elements(data->'pages') p where p->>'id'<>'method') || jsonb_build_array($j${"id": "method", "t": {"ar": "طريقة العمل", "en": "How it works"}, "b": {"ar": "## من أين تأتي المعلومات\n- كل جرعة وتداخل من **النشرة الرسمية للدواء**: FDA / DailyMed أولاً (أحدث نسخة)، وإن لم توجد فمن EMA أو eMC (بريطانيا) أو ANSM (فرنسا).\n- لكل نشرة رقم في قائمة المصادر مع اسمها وتاريخها ورابطها، ويظهر الرقم بجانب كل معلومة.\n- تصنيف **AWaRe** (وصول، مراقبة، احتياط) من منظمة الصحة العالمية 2023.\n\n## كيف تُحسب وظيفة الكلى\n- **تصفية الكرياتينين (Cockcroft-Gault):** `CrCl = (140 - Age) × Weight ÷ (72 × SCr)`، وتُضرب في 0.85 للنساء.\n- **الوزن المثالي (IBW):** للرجال 50 كغ وللنساء 45.5 كغ، ويضاف 2.3 كغ لكل إنش من الطول فوق 60 إنشاً (152.4 سم).\n- **الوزن المعدّل:** يُستعمل إذا زاد الوزن الفعلي على 120% من المثالي: `AdjBW = 0.4 × (ABW - IBW) + IBW`. وإذا حددت النشرة وزناً آخر للجرعة بالكيلوغرام تتبعها الحاسبة.\n- **eGFR (MDRD):** للأدوية التي تحدد نشرتها الجرعة بمعدل الترشيح: `eGFR = 175 × SCr^-1.154 × Age^-0.203`، وتُضرب في 0.742 للنساء.\n\n## كيف تُختار الجرعة\n- لكل دواء جدول قواعد مأخوذ من نشرته، مرتّب كما في النشرة.\n- تُفحص القواعد بالترتيب (نوع العدوى، التصفية، العمر، الوزن)، و**أول قاعدة تطابق** هي النتيجة، مع مصدرها.\n- إذا لم تذكر النشرة حداً رقمياً للكلى، تسأل الحاسبة **نعم / لا** بدل تخمين رقم.\n\n## المراجعة والجودة\n- أي محتوى طبي جديد أو معدّل لا يظهر للزوار حتى يعتمده الصيدلي المسؤول وينشره.\n- اختبارات آلية قبل كل نسخة: نحو 2000 فحص لقواعد الجرعات مقارنة بأرقام النشرات، وفحص الأدوية المئة ومصادرها، وفحص الواجهة على الهاتف والآيباد والكمبيوتر بالعربية والإنجليزية.\n\n## حدود الاستخدام\n- النتيجة مساعدة للصيدلي والطبيب، ولا تغني عن الحكم السريري ولا عن قراءة النشرة كاملة.", "en": "## Where the information comes from\n- Every dose and interaction comes from the **official drug label**: FDA / DailyMed first (newest version), otherwise EMA, eMC (UK) or ANSM (France).\n- Each label has a number in the sources list with its name, date and link, and that number appears next to every item.\n- The **AWaRe** group (Access, Watch, Reserve) is from the WHO 2023 classification.\n\n## How kidney function is calculated\n- **Creatinine clearance (Cockcroft-Gault):** `CrCl = (140 - Age) × Weight ÷ (72 × SCr)`, × 0.85 for women.\n- **Ideal body weight (IBW):** 50 kg for men and 45.5 kg for women, + 2.3 kg per inch of height above 60 inches (152.4 cm).\n- **Adjusted weight:** used when actual weight is over 120% of ideal: `AdjBW = 0.4 × (ABW - IBW) + IBW`. If a label names another weight for mg/kg doses, the calculator follows it.\n- **eGFR (MDRD):** for drugs whose label doses by filtration rate: `eGFR = 175 × SCr^-1.154 × Age^-0.203`, × 0.742 for women.\n\n## How the dose is chosen\n- Each drug has a table of rules taken from its label, in the label's order.\n- The rules are checked in order (infection, clearance, age, weight) and the **first rule that matches** is the result, with its source.\n- If the label gives no kidney number, the calculator asks **yes / no** instead of guessing a number.\n\n## Review and quality\n- New or edited medical content does not reach visitors until the responsible pharmacist approves and publishes it.\n- Automated tests before every version: about 2000 checks of the dose rules against the label numbers, a check of the 100 drugs and their sources, and the interface on phone, iPad and computer in Arabic and English.\n\n## Limits\n- The result supports the pharmacist and doctor; it does not replace clinical judgement or reading the full label."}}$j$::jsonb)) where id='draft';